const nav = [
  ['dashboard', '◫', '运行总览'],
  ['orders', '▤', '维修工单'],
  ['tasks', '◎', '维保计划'],
  ['devices', '▦', '设备台账'],
];

function statusClass(status) {
  if (status === '待派单' || status === '异常待处理') return 'amber';
  if (status === '维修中' || status === '检修中') return 'blue';
  if (status === '待验收') return 'purple';
  return 'green';
}

function orderRows(orders, h) {
  return orders.map(order => `<article class="tower-order" data-searchable="${h(`${order.id} ${order.title} ${order.device}`)}">
    <div class="tower-order-mark ${order.priority === '紧急' ? 'is-urgent' : ''}"></div>
    <div class="tower-order-main"><strong>${h(order.title)}</strong><span>${h(order.id)} <i>·</i> ${h(order.device)} <i>·</i> ${h(order.location)}</span></div>
    <span class="tower-chip ${statusClass(order.status)}">${h(order.status)}</span>
    <span class="tower-order-time">${h(order.age)}</span>
    <button class="tower-row-action" type="button" data-action="open-order" data-id="${h(order.id)}" aria-label="查看 ${h(order.id)}">↗</button>
  </article>`).join('');
}

function taskRows(tasks, h) {
  return tasks.map(task => `<article class="tower-task" data-searchable="${h(`${task.title} ${task.device}`)}">
    <span class="tower-task-serial">${h(task.id)}</span>
    <div><strong>${h(task.title)}</strong><span>${h(task.device)} · ${h(task.steps)} · ${h(task.owner)}</span></div>
    <span class="tower-task-due ${task.due.includes('超期') ? 'late' : ''}">${h(task.due)}</span>
    ${task.status === '待执行' ? `<button type="button" data-action="complete-task" data-id="${h(task.id)}">完成</button>` : '<span class="tower-task-done">已完成</span>'}
  </article>`).join('');
}

function devices(devices, h) {
  return devices.map(device => `<article class="tower-device" data-searchable="${h(`${device.name} ${device.code} ${device.place}`)}">
    <div class="tower-device-symbol">${h(device.kind.slice(0,1))}</div>
    <div class="tower-device-name"><strong>${h(device.name)}</strong><span>${h(device.code)} · ${h(device.place)}</span></div>
    <span class="tower-chip ${statusClass(device.health)}">${h(device.health)}</span>
    <button class="tower-row-action" type="button" data-action="open-device" data-id="${h(device.id)}" aria-label="查看 ${h(device.name)}">↗</button>
  </article>`).join('');
}

function dashboard(m, h) {
  const values = [14, 24, 18, 34, 29, 42, 31];
  return `<div class="tower-intro"><div><span class="tower-eyebrow">CONTROL ROOM / 本班运行态势</span><h1>设备运行总览</h1><p>聚焦异常、工单与到期任务。以下均为演示数据。</p></div><div class="tower-shift"><span class="tower-live"></span> 白班在线 <small>09 月 29 日</small></div></div>
    <div class="tower-metrics">
      <section><span>设备总量 <b>01 / ASSETS</b></span><strong>${m.devices.length.toString().padStart(2,'0')}</strong><small>台已建档设备</small></section>
      <section><span>未关闭工单 <b>02 / ORDERS</b></span><strong>${m.activeOrders.toString().padStart(2,'0')}</strong><small>件需要持续跟踪</small></section>
      <section class="signal"><span>紧急待处理 <b>03 / PRIORITY</b></span><strong>${m.urgentOrders.toString().padStart(2,'0')}</strong><small>件需优先响应</small></section>
      <section><span>待执行维保 <b>04 / PLANS</b></span><strong>${m.pendingTasks.toString().padStart(2,'0')}</strong><small>项计划任务</small></section>
    </div>
    <div class="tower-grid">
      <section class="tower-panel tower-work"><header><div><small>01 / WORK ORDERS</small><h2>当前维修工单</h2></div><button type="button" data-action="nav" data-view="orders">全部工单 ↗</button></header>${orderRows(m.orders.filter(item=>item.status!=='已关闭').slice(0,3),h)}</section>
      <section class="tower-panel tower-chart"><header><div><small>02 / ACTIVITY</small><h2>近七日响应</h2></div></header><div class="tower-chart-bars" aria-label="近七日响应示意图">${values.map((value,i)=>`<div><span style="height:${value*2}px" title="周${'一二三四五六日'[i]} · ${value} 件"></span><small>${'一二三四五六日'[i]}</small></div>`).join('')}</div><p>模拟分布 · 辅助比较布局节奏</p></section>
      <section class="tower-panel tower-maint"><header><div><small>03 / MAINTENANCE</small><h2>今日维保任务</h2></div><button type="button" data-action="nav" data-view="tasks">查看任务 ↗</button></header>${taskRows(m.tasks.slice(0,3),h)}</section>
      <section class="tower-panel tower-focus"><small>当班重点 / SHIFT PRIORITY</small><strong>先处理紧急异常，随后完成到期点检。</strong><p>将停机风险、工单流转和保养任务放在同一屏，不需要在多个页面寻找待办。</p><button type="button" data-action="new-report">+ 快速报修</button></section>
    </div>`;
}

function orders(m, h) {
  return `<div class="tower-page-head"><div><span class="tower-eyebrow">WORK ORDERS / 维修流转</span><h1>维修工单</h1><p>按状态切换，打开工单后可继续流转演示流程。</p></div><button class="tower-primary" type="button" data-action="new-report">+ 新建报修</button></div>
    <section class="tower-panel tower-list-page"><div class="tower-list-tools"><div class="tower-filters">${[['all','全部'],['待派单','待派单'],['维修中','维修中'],['待验收','待验收']].map(([value,label])=>`<button type="button" data-action="filter" data-filter="${value}" class="${m.filter===value?'active':''}">${label}</button>`).join('')}</div><input data-search-input type="search" aria-label="搜索工单" placeholder="搜索编号、设备或故障"></div>${orderRows(m.ordersInView,h)}</section>`;
}

function tasks(m,h){return `<div class="tower-page-head"><div><span class="tower-eyebrow">PREVENTIVE / 今日执行</span><h1>保养与点检</h1><p>保留计划时间、设备和执行人，完成按钮会更新原型任务状态。</p></div></div><section class="tower-panel tower-list-page"><header><div><small>计划任务</small><h2>${m.tasks.length} 项任务</h2></div></header>${taskRows(m.tasks,h)}</section>`;}
function assets(m,h){return `<div class="tower-page-head"><div><span class="tower-eyebrow">ASSET REGISTER / 设备索引</span><h1>设备台账</h1><p>聚合设备位置与业务状态，选择设备可查看详情并发起报修。</p></div><button class="tower-primary" type="button" data-action="new-report">+ 发起报修</button></div><section class="tower-panel tower-list-page"><div class="tower-list-tools"><span>已建档设备 / ${m.devices.length}</span><input data-search-input type="search" aria-label="搜索设备" placeholder="按名称、编号或位置搜索"></div>${devices(m.devices,h)}</section>`;}

const css = `<style>
.tower{--modal-bg:#142936;--modal-ink:#e8f4f4;--modal-soft:#1c3542;--modal-accent:#55cfc0;--modal-muted:#9cb7bf;--modal-line:#31505c;min-height:100vh;background:#0d1a24;color:#e6f1f2;font-family:Inter,"Microsoft YaHei",system-ui,sans-serif}
.tower button{font:inherit}.tower-shell{min-height:100vh;display:grid;grid-template-columns:232px minmax(0,1fr)}.tower-sidebar{background:#0a151e;border-right:1px solid #203440;display:flex;flex-direction:column;padding:27px 16px 26px}.tower-brand{display:flex;align-items:center;gap:11px;padding:0 10px 35px}.tower-brand-mark{height:36px;width:36px;border:1px solid #498f8b;border-radius:9px;display:grid;place-items:center;background:#173337;color:#78e0d1;font-size:17px;font-weight:700}.tower-brand strong{display:block;letter-spacing:.04em;font-size:14px}.tower-brand small{display:block;color:#608490;font-size:8px;letter-spacing:.15em;margin-top:4px}.tower-nav-label{font-size:10px;letter-spacing:.18em;color:#547581;margin:0 13px 11px}.tower-nav{display:grid;gap:4px}.tower-nav button{display:flex;align-items:center;gap:13px;border:0;background:transparent;color:#8ea8b1;width:100%;padding:12px 13px;text-align:left;border-radius:7px;font-size:12px}.tower-nav button b{font-size:17px;font-weight:400;width:19px;text-align:center;color:#64818c}.tower-nav button[aria-current=page]{background:#173239;color:#e8fffd;box-shadow:inset 2px 0 #5bcfc0}.tower-nav button:hover{background:#162b35;color:#f5ffff}.tower-sidebar-bottom{margin-top:auto;background:#122b32;border:1px solid #23424b;border-radius:10px;padding:14px 13px;font-size:11px;color:#a8c6cc;line-height:1.7}.tower-sidebar-bottom strong{display:block;color:#d7f4f1;margin-bottom:3px}.tower-sidebar-bottom i{display:inline-block;width:6px;height:6px;background:#71d3b0;border-radius:50%;margin-right:6px}.tower-content{min-width:0}.tower-top{height:64px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #223744;padding:0 34px;color:#86a0a9;font-size:11px}.tower-top strong{color:#bfd3d7;font-weight:500}.tower-top-right{display:flex;gap:10px;align-items:center}.tower-top button{border:1px solid #31505b;background:#162b37;color:#b9d8db;border-radius:7px;padding:8px 12px;font-size:11px}.tower-top button:hover{background:#214550}.tower-top .tower-notice{position:relative;width:35px;text-align:center;padding:7px}.tower-top .tower-notice em{position:absolute;right:-4px;top:-7px;background:#f8a876;border-radius:10px;color:#11222b;padding:1px 5px;font-size:9px;font-style:normal}.tower-main{max-width:1520px;margin:auto;padding:31px 34px 100px}.tower-main>*{animation:tower-enter 230ms ease-out both}.tower-eyebrow{font-size:10px;letter-spacing:.17em;color:#64c0b9;font-weight:650}.tower-intro,.tower-page-head{display:flex;justify-content:space-between;align-items:flex-end;gap:20px;margin-bottom:25px}.tower-intro h1,.tower-page-head h1{font-size:28px;letter-spacing:-.02em;margin:7px 0 5px}.tower-intro p,.tower-page-head p{font-size:12px;color:#829ca7;margin:0;line-height:1.6}.tower-shift{background:#152e36;border:1px solid #28505a;border-radius:6px;padding:11px 15px;color:#bfe4df;font-size:12px;white-space:nowrap}.tower-shift small{margin-left:11px;color:#79a4a6}.tower-live{display:inline-block;width:7px;height:7px;background:#61d5a2;border-radius:50%;margin-right:6px;box-shadow:0 0 0 4px #61d5a21d}.tower-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-bottom:17px}.tower-metrics section{background:#142734;border:1px solid #25404e;border-radius:10px;padding:19px 21px;min-height:132px}.tower-metrics section.signal{border-color:#785845;background:linear-gradient(145deg,#1e2c32,#2d2b2a)}.tower-metrics section>span{display:flex;justify-content:space-between;color:#a8c2c7;font-size:11px}.tower-metrics b{font-weight:500;color:#557b84;font-size:9px;letter-spacing:.08em}.tower-metrics strong{display:block;color:#e6f7f5;font-size:36px;line-height:1.2;margin:14px 0 4px;font-weight:600}.tower-metrics .signal strong{color:#f8b376}.tower-metrics small{font-size:10px;color:#7294a0}.tower-grid{display:grid;grid-template-columns:minmax(0,1.75fr) minmax(270px,1fr);gap:17px}.tower-panel{background:#142734;border:1px solid #25404e;border-radius:10px;min-width:0;overflow:hidden}.tower-panel header{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:20px 22px;border-bottom:1px solid #28404a}.tower-panel header small{font-size:9px;letter-spacing:.14em;color:#639899}.tower-panel h2{font-size:15px;margin:5px 0 0;font-weight:600}.tower-panel header button{border:0;background:transparent;color:#6ccdc2;font-size:11px}.tower-order,.tower-task,.tower-device{display:flex;align-items:center;gap:15px;padding:17px 21px;border-bottom:1px solid #233a46;min-height:72px}.tower-order:last-child,.tower-task:last-child,.tower-device:last-child{border:0}.tower-order:hover,.tower-task:hover,.tower-device:hover{background:#1a303c}.tower-order-mark{width:3px;align-self:stretch;background:#4892a0;border-radius:5px;flex:none}.tower-order-mark.is-urgent{background:#eca166}.tower-order-main,.tower-task>div,.tower-device-name{min-width:0;flex:1}.tower-order-main strong,.tower-task strong,.tower-device strong{display:block;font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.tower-order-main span,.tower-task span,.tower-device span{display:block;font-size:10px;color:#6c909e;margin-top:7px}.tower-order-main i{font-style:normal;margin:0 3px}.tower-chip{display:inline-block!important;margin:0!important;padding:5px 7px;border-radius:4px;white-space:nowrap;font-size:10px!important}.tower-chip.amber{background:#4d3b2e;color:#f4c18c}.tower-chip.blue{background:#244454;color:#9cd0f0}.tower-chip.purple{background:#383652;color:#beb9f1}.tower-chip.green{background:#24453f;color:#88d6b2}.tower-order-time{color:#77929a!important;white-space:nowrap;font-size:10px!important;margin:0!important}.tower-row-action{border:1px solid #42616a;background:transparent;color:#8fded2;border-radius:5px;width:28px;height:28px;flex:none}.tower-row-action:hover{background:#2a5454}.tower-chart-bars{display:flex;align-items:flex-end;justify-content:space-between;gap:7px;height:156px;padding:24px 25px 0}.tower-chart-bars div{display:grid;align-items:end;justify-items:center;flex:1;height:100%}.tower-chart-bars span{width:min(100%,23px);background:linear-gradient(#6de0d3,#225767);border-radius:4px 4px 0 0;max-height:100%}.tower-chart-bars small{margin:8px 0 0;color:#7898a2;font-size:10px}.tower-chart>p{padding:25px;margin:0;color:#688994;font-size:10px}.tower-maint .tower-task{min-height:69px}.tower-task-serial{font-size:10px!important;color:#63c5bc!important;font-weight:600;min-width:55px;margin:0!important}.tower-task-due{white-space:nowrap!important;color:#a1b8bd!important;margin:0!important}.tower-task-due.late{color:#e3a477!important}.tower-task button{background:#224c4d;border:1px solid #376a68;color:#a9ebe3;padding:6px 10px;border-radius:5px;font-size:10px}.tower-task-done{color:#8fbdad!important}.tower-focus{padding:24px;display:flex;flex-direction:column;background:linear-gradient(125deg,#163a42,#15303b)}.tower-focus small{font-size:10px;color:#77bdb7;letter-spacing:.13em}.tower-focus strong{font-size:20px;line-height:1.4;max-width:290px;margin:22px 0 10px}.tower-focus p{color:#95b5b9;font-size:11px;line-height:1.8;margin:0 0 23px}.tower-focus button,.tower-primary{align-self:flex-start;border:1px solid #4fb4a8!important;background:#2a847c!important;color:#eafffb!important;border-radius:6px!important;padding:10px 15px!important;font-weight:600;font-size:11px!important}.tower-list-page{margin-top:24px}.tower-list-tools{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:17px 22px;border-bottom:1px solid #28404a;color:#8eabb1;font-size:11px}.tower-list-tools input{width:260px;background:#0f222d;border:1px solid #34515d;color:#e5f5f3;border-radius:5px;padding:10px 12px;outline:none}.tower-filters{display:flex;gap:5px;flex-wrap:wrap}.tower-filters button{border:1px solid transparent;background:transparent;color:#8ea9af;padding:7px 11px;border-radius:5px;font-size:11px}.tower-filters button.active{color:#aff3e8;background:#1b4144;border-color:#39736e}.tower-device-symbol{width:35px;height:35px;border-radius:7px;background:#24464a;color:#94d9d1;display:grid;place-items:center;font-weight:700}.tower .proto-modal{border:1px solid #315862}.tower .proto-modal-actions button{color:#071e20!important}.tower .proto-modal form input,.tower .proto-modal form select{background:#112531}.tower .proto-modal-close:hover{background:#2b505a}@keyframes tower-enter{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}
@media(max-width:1160px){.tower-grid{grid-template-columns:1fr}.tower-metrics{grid-template-columns:repeat(2,1fr)}}
@media(max-width:760px){.tower-shell{display:block}.tower-sidebar{padding:12px 16px;position:relative}.tower-brand{padding:0 0 10px}.tower-brand-mark{width:29px;height:29px}.tower-nav-label,.tower-sidebar-bottom{display:none}.tower-nav{display:flex;overflow:auto}.tower-nav button{white-space:nowrap;padding:8px 10px}.tower-top{height:auto;min-height:51px;padding:11px 18px}.tower-top strong{display:none}.tower-main{padding:22px 15px 90px}.tower-intro,.tower-page-head{align-items:start}.tower-intro h1,.tower-page-head h1{font-size:24px}.tower-shift{display:none}.tower-metrics{gap:9px}.tower-metrics section{min-height:112px;padding:13px}.tower-metrics strong{font-size:29px}.tower-grid{gap:12px}.tower-panel header{padding:16px}.tower-order,.tower-task,.tower-device{padding:15px;gap:9px;flex-wrap:wrap}.tower-order-main{flex-basis:62%}.tower-order-time{display:none!important}.tower-list-tools{padding:14px;flex-wrap:wrap}.tower-list-tools input{width:100%}}
@media(prefers-reduced-motion:reduce){.tower-main>*{animation:none}}
</style>`;

export default {
  className: 'tower',
  render(m,h) {
    return `${css}<div class="tower-shell"><aside class="tower-sidebar"><div class="tower-brand"><span class="tower-brand-mark">维</span><div><strong>设备维保中心</strong><small>EQUIPMENT CONTROL</small></div></div><div class="tower-nav-label">WORKSPACE / 工作区</div><nav class="tower-nav" aria-label="工作区导航">${nav.map(([view,icon,label])=>`<button type="button" data-action="nav" data-view="${view}" ${m.view===view?'aria-current="page"':''}><b aria-hidden="true">${icon}</b>${label}</button>`).join('')}</nav><div class="tower-sidebar-bottom"><strong><i></i>系统演示模式</strong>数据仅用于方案比较，所有操作都可在本页体验。</div></aside><div class="tower-content"><header class="tower-top"><strong>试点工厂 / 设备管理 / ${h(m.labels[m.view])}</strong><div class="tower-top-right"><span>2026.09.29　白班</span><button type="button" data-action="new-report">+ 报修</button><button class="tower-notice" type="button" data-action="notifications" aria-label="消息中心">◉${m.unread?`<em>${m.unread}</em>`:''}</button></div></header><div class="tower-main">${m.view==='dashboard'?dashboard(m,h):m.view==='orders'?orders(m,h):m.view==='tasks'?tasks(m,h):assets(m,h)}</div></div></div>`;
  }
};
